"""Regenerate public share entry pages and the router catalog (Python 3, no dependencies)."""
from pathlib import Path
import html
import json

ROOT = Path(__file__).resolve().parents[1]
pages = json.loads((ROOT / 'share-pages.json').read_text())
assert len({p['route'] for p in pages}) == len(pages)
assert len({p['path'] for p in pages}) == len(pages)
(ROOT / 'share-pages.js').write_text(
    '// Generated by scripts/build-share-pages.py from share-pages.json.\n'
    + 'window.FD_SHARE_PAGES = ' + json.dumps(pages, ensure_ascii=False, indent=2) + ';\n'
)
for page in pages:
    if not page['entry']:
        continue  # Existing maps and contest retain their own pages.
    target = ROOT / page['path'].strip('/') / 'index.html'
    target.parent.mkdir(parents=True, exist_ok=True)
    title, description = html.escape(page['title'], quote=True), html.escape(page['description'], quote=True)
    url = 'https://familydaystay.com' + page['path']
    route = page['route']
    target.write_text(f'''<!doctype html>
<!-- Generated by scripts/build-share-pages.py; edit share-pages.json. -->
<html lang="ar" dir="rtl">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>{title}</title>
<meta name="description" content="{description}">
<link rel="canonical" href="{url}">
<meta property="og:type" content="website">
<meta property="og:site_name" content="يوم العائلة">
<meta property="og:locale" content="ar_SA">
<meta property="og:url" content="{url}">
<meta property="og:title" content="{title}">
<meta property="og:description" content="{description}">
<meta name="twitter:card" content="summary">
<meta name="twitter:title" content="{title}">
<meta name="twitter:description" content="{description}">
<style>html{{background:#04111e;color:#f0f5f7;font-family:Arial,sans-serif}}body{{margin:0;min-height:100vh;display:grid;place-items:center}}main{{max-width:36rem;padding:24px;text-align:center;line-height:1.7}}a{{color:#9ac8d4}}</style>
<script>
// Crawlers read the title above; visitors use the existing view and Back navigation.
var route={json.dumps(route)};
if(route.indexOf('cabin=')===0 && new URLSearchParams(location.search).get('from')==='map') route+='&from=map';
location.replace('/'+location.search+'#'+route);
</script>
</head>
<body><main><h1>{title}</h1><p>{description}</p><a href="/#{html.escape(route, quote=True)}">فتح الصفحة</a></main></body>
</html>
''')
print(f'Built catalog with {len(pages)} routes and {sum(p["entry"] for p in pages)} static share pages.')
